item.description:
Module 1: Storage & Database (Lưu trữ và Cơ sở dữ liệu)Thiết lập bảng DynamoDB dạng Single Table để lưu trữ dữ liệu chung và S3 bucket để lưu trữ tài nguyên/tệp tin của ứng dụng.
Tạo tệp lib/storage-stack.ts:
import * as cdk from 'aws-cdk-lib'; import * as dynamodb from 'aws-cdk-lib/aws-dynamodb'; import * as s3 from 'aws-cdk-lib/aws-s3'; import { Construct } from 'constructs'; export class StorageStack extends cdk.Stack { public readonly table: dynamodb.Table; public readonly assetBucket: s3.Bucket; constructor(scope: Construct, id: string, props?: cdk.StackProps) { super(scope, id, props); // Khởi tạo DynamoDB Single Table cho dữ liệu ứng dụng nói chung this.table = new dynamodb.Table(this, 'AppSingleTable', { partitionKey: { name: 'PK', type: dynamodb.AttributeType.STRING }, sortKey: { name: 'SK', type: dynamodb.AttributeType.STRING }, billingMode: dynamodb.BillingMode.PAY_PER_REQUEST, // Thanh toán On-Demand pointInTimeRecovery: true, // Tự động backup liên tục removalPolicy: cdk.RemovalPolicy.DESTROY, // Tự động xóa khi destroy stack }); // Tạo S3 Bucket riêng tư để lưu trữ tài nguyên ứng dụng this.assetBucket = new s3.Bucket(this, 'AssetStorageBucket', { encryption: s3.BucketEncryption.S3_MANAGED, blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL, // Chặn hoàn toàn public access removalPolicy: cdk.RemovalPolicy.DESTROY, autoDeleteObjects: true, }); } }

Module 3: Security & Permissions (Bảo mật & Phân quyền)Thiết lập Cognito User Pool cho đăng nhập và tạo các chính sách IAM chi tiết tuân theo nguyên tắc phân quyền tối thiểu (Least Privilege).
Tạo tệp lib/security-stack.ts:
import * as cdk from 'aws-cdk-lib'; import * as cognito from 'aws-cdk-lib/aws-cognito'; import * as iam from 'aws-cdk-lib/aws-iam'; import { Construct } from 'constructs'; export class SecurityStack extends cdk.Stack { public readonly userPool: cognito.UserPool; public readonly userPoolClient: cognito.UserPoolClient; constructor(scope: Construct, id: string, props?: cdk.StackProps) { super(scope, id, props); this.userPool = new cognito.UserPool(this, 'AppUserPool', { userPoolName: 'app-user-pool', selfSignUpEnabled: true, signInAliases: { email: true }, autoVerify: { email: true }, passwordPolicy: { minLength: 8, requireLowercase: true, requireUppercase: true, requireDigits: true, requireSymbols: true, }, removalPolicy: cdk.RemovalPolicy.DESTROY, }); this.userPoolClient = new cognito.UserPoolClient(this, 'AppUserPoolClient', { userPool: this.userPool, generateSecret: false, }); // Custom role cho hệ thống thông báo (Quyền tối thiểu) const notificationRole = new iam.Role(this, 'NotificationPublishRole', { assumedBy: new iam.ServicePrincipal('lambda.amazonaws.com'), description: 'Role gửi thông báo với các quyền tối giản', }); notificationRole.addToPolicy(new iam.PolicyStatement({ actions: ['sns:Publish'], resources: ['*'], effect: iam.Effect.ALLOW, })); } }
